    if(!['admin','doctor'].includes(me.role))throw new Error('إنشاء جلسة متاح للطبيب والإدارة فقط.');const room='iwan-test-'+crypto.randomUUID().replaceAll('-','').slice(0,16);const meetingUrl='https://meet.jit.si/'+room;const {data,error}=await sb.from('video_sessions').insert({appointment_id:body.appointmentId,created_by:me.id,meeting_url:meetingUrl}).select().single();if(error)throw error;return {id:data.id,meetingUrl};
