async function refreshAvailability(){ const doctor=$('#bookingDoctor')?.value; const date=$('#bookingDate')?.value; const timeSelect=$('#bookingTime'); if(!doctor||!date||!timeSelect)return; try{ const d=await api('/api/availability?doctorId='+encodeURIComponent(doctor)+'&date='+encodeURIComponent(date)); timeSelect.innerHTML=d.slots.length?d.slots.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join(''):'<option value="">لا توجد مواعيد متاحة</option>'; const fee=$('#bookingFee'); if(fee)fee.textContent='سعر الجلسة التجريبي: '+Number(d.fee).toLocaleString('ar-EG')+' جنيه مصري'; }catch(e){timeSelect.innerHTML='<option value="">تعذر تحميل المواعيد</option>';toast(e.message,true)} }
$('#showRegister').addEventListener('click',()=>{ $('#registerForm').classList.remove('hidden'); $('#loginForm').classList.add('hidden'); $('#registerError').textContent=''; });
$('#cancelRegister').addEventListener('click',()=>{ $('#registerForm').classList.add('hidden'); $('#loginForm').classList.remove('hidden'); $('#registerError').textContent=''; });
$('#registerRole').addEventListener('change',registrationFields);registrationFields();$('#registerForm').addEventListener('submit',async e=>{e.preventDefault();$('#registerError').textContent='';const f=new FormData(e.currentTarget);const data=Object.fromEntries(f.entries());if(data.weeklySchedule)data.weeklySchedule=JSON.stringify({});try{const d=await api('/api/register',{method:'POST',body:JSON.stringify(data)});alert(d.message||'تم إرسال طلب الحساب');e.currentTarget.reset();registrationFields();$('#registerForm').classList.add('hidden');$('#loginForm').classList.remove('hidden')}catch(err){$('#registerError').textContent=err.message}});
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();$('#loginError').textContent='';const f=new FormData(e.currentTarget);try{const d=await api('/api/login',{method:'POST',body:JSON.stringify({username:f.get('username'),password:f.get('password')})});state.token=d.token;state.user=d.user;localStorage.setItem('ewan_token',state.token);showLoggedIn();await navigate('home')}catch(err){$('#loginError').textContent=err.message}});
