$('#nav').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)navigate(b.dataset.page)});$('#mobileNav').addEventListener('click',e=>{const b=e.target.closest('[data-mobile-page]');if(b)navigate(b.dataset.mobilePage)});$('#registerRole').addEventListener('change',registrationFields);
$('#pageContent').addEventListener('click',async e=>{const book=e.target.closest('[data-book-doctor]');if(book){state.preselectedDoctorId=book.dataset.bookDoctor;state.page='newAppointment';$('#pageTitle').textContent='حجز موعد';renderPage();if($('#bookingDoctor'))$('#bookingDoctor').value=state.preselectedDoctorId;await refreshAvailability();return}const b=e.target.closest('[data-go]');if(b){if(b.dataset.go==='newAppointment'){state.page='newAppointment';$('#pageTitle').textContent='حجز موعد';renderPage()}else navigate(b.dataset.go)}if(e.target.id==='testPaySuccess'||e.target.id==='testPayFail'){try{const intent=await api('/api/payments/test-intent',{method:'POST',body:JSON.stringify({appointmentId:state.pendingPaymentAppointmentId})});const result=await api('/api/payments/test-confirm',{method:'POST',body:JSON.stringify({paymentId:intent.id,result:e.target.id==='testPaySuccess'?'success':'failure'})});toast(result.notice);state.pendingPaymentAppointmentId=null;await navigate('appointments')}catch(err){toast(err.message,true)}}const apptAction=e.target.closest('[data-appt-action]');if(apptAction){try{let body={action:apptAction.dataset.apptAction};if(body.action==='reschedule'){body.date=prompt('التاريخ المقترح (YYYY-MM-DD)');if(!body.date)return;body.time=prompt('الوقت المقترح (HH:MM)');if(!body.time)return;}await api('/api/appointments/'+encodeURIComponent(apptAction.dataset.apptId)+'/respond',{method:'POST',body:JSON.stringify(body)});toast('تم إرسال قرارك للمريض والاستقبال');await loadData();await navigate('appointments')}catch(err){toast(err.message,true)}}const approve=e.target.closest('[data-approve]');if(approve){try{await api('/api/users/'+encodeURIComponent(approve.dataset.approve)+'/approval',{method:'PATCH',body:JSON.stringify({status:approve.dataset.status})});toast(approve.dataset.status==='approved'?'تمت الموافقة على الحساب':'تم رفض الحساب');await navigate('accounts')}catch(err){toast(err.message,true)}}const resetPassword=e.target.closest('[data-reset-password]');if(resetPassword){const form=resetPassword.closest('form');const password=form.elements.newPassword.value;if(password.length<10){toast('كلمة المرور يجب ألا تقل عن 10 أحرف',true);return}if(!confirm('تأكيد تغيير كلمة مرور هذا المستخدم؟'))return;try{const result=await api('/api/users/'+encodeURIComponent(resetPassword.dataset.resetPassword)+'/password',{method:'PATCH',body:JSON.stringify({password})});toast(result.message||'تم تغيير كلمة المرور');form.reset()}catch(err){toast(err.message,true)}}if(e.target.id==='refreshAccounts')navigate('accounts');if(e.target.id==='exportFinance'){const csv=['المريض,الطبيب,التاريخ,الوقت,القيمة,الحالة',...state.appointments.map(a=>[a.patientName,doctorName(a.doctorId),a.date,a.time,a.fee||0,a.status].map(v=>'+String(v??).replace(/"/g,)+').join(','))].join('\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='ewan-finance.csv';link.click();URL.revokeObjectURL(link.href)}if(e.target.id==='downloadBackup'){try{const backup=await api('/api/admin/backup');const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='ewan-backup-'+new Date().toISOString().replace(/[:.]/g,'-')+'.json';link.click();URL.revokeObjectURL(link.href);toast('تم تنزيل النسخة الاحتياطية')}catch(err){toast(err.message,true)}}if(e.target.id==='refreshAudit'){try{state.audit=await api('/api/audit');renderPage()}catch(err){toast(err.message,true)}}});
$('#pageContent').addEventListener('change',async e=>{if(e.target.id==='bookingDoctor'||e.target.id==='bookingDate'){await refreshAvailability();return}const s=e.target.closest('[data-status-id]');if(s){try{await api('/api/appointments/'+encodeURIComponent(s.dataset.statusId),{method:'PATCH',body:JSON.stringify({status:s.value})});toast('تم تحديث حالة الحجز');await loadData();renderPage()}catch(err){toast(err.message,true);await navigate('appointments')}}});
$('#pageContent').addEventListener('change',async e=>{if(e.target.id!=='restoreBackupFile')return;const file=e.target.files?.[0];if(!file)return;if(file.size>24*1024*1024){toast('حجم ملف النسخة يتجاوز الحد المسموح (24 ميجابايت)',true);e.target.value='';return}if(!confirm('تحذير: استعادة النسخة ستستبدل كل البيانات الحالية. هل أنشأت نسخة احتياطية حديثة وتريد المتابعة؟')){e.target.value='';return}try{const backup=JSON.parse(await file.text());const result=await api('/api/admin/restore',{method:'POST',body:JSON.stringify(backup)});toast(result.message||'تمت الاستعادة');await navigate('home')}catch(err){toast(err.message||'ملف النسخة غير صالح',true)}finally{e.target.value=''}});
$('#pageContent').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{if(e.target.matches('[data-permission-user]')){const permissions=[...e.target.querySelectorAll('input[name=permission]:checked')].map(x=>x.value);await api('/api/users/'+encodeURIComponent(e.target.dataset.permissionUser)+'/permissions',{method:'PATCH',body:JSON.stringify({permissions})});toast('تم حفظ صلاحيات المستخدم');}else if(e.target.matches('[data-fee-doctor]')){await api('/api/doctors/'+encodeURIComponent(e.target.dataset.feeDoctor),{method:'PATCH',body:JSON.stringify({feeEgyptian:Number(f.get('feeEgyptian')),feeForeign:Number(f.get('feeForeign'))})});toast('تم تحديث أسعار الجلسات');await navigate('doctors')}else if(e.target.id==='appointmentForm'){const appointment=await api('/api/appointments',{method:'POST',body:JSON.stringify(Object.fromEntries(f.entries()))});toast(state.user.role==='patient'?'تم إنشاء الحجز المبدئي، انتقل للدفع التجريبي':'تم حفظ طلب الحجز بنجاح');if(state.user.role==='patient'){state.pendingPaymentAppointmentId=appointment.id;state.appointments=await api('/api/appointments');await navigate('payment')}else await navigate('appointments')}else if(e.target.id==='doctorForm'){await api('/api/doctors',{method:'POST',body:JSON.stringify(Object.fromEntries(f.entries()))});toast('تمت إضافة الطبيب');await navigate('doctors')}else if(e.target.id==='pharmacyForm'){await api('/api/pharmacy',{method:'POST',body:JSON.stringify(Object.fromEntries(f.entries()))});toast('تمت إضافة الصنف');await navigate('pharmacy')}else if(e.target.id==='scheduleForm'){const weeklySchedule={};for(let k=0;k<7;k++)weeklySchedule[k]={enabled:e.target.elements['enabled_'+k].checked,start:e.target.elements['start_'+k].value,end:e.target.elements['end_'+k].value,duration:Number(e.target.elements['duration_'+k].value)};await api('/api/doctor/schedule',{method:'PUT',body:JSON.stringify({weeklySchedule})});toast('تم حفظ الجدول الأسبوعي');}else if(e.target.id==='documentForm'){const file=e.target.elements.file.files[0];if(!file)throw new Error('اختر ملفًا أولًا');if(file.size>1300000)throw new Error('حجم الملف يجب ألا يتجاوز 1.3 ميجابايت');const dataBase64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('تعذر قراءة الملف'));reader.readAsDataURL(file)});await api('/api/documents',{method:'POST',body:JSON.stringify({name:file.name,mime:file.type,dataBase64})});toast('تم رفع الملف التجريبي');await navigate('medical')}else if(e.target.id==='clinicalForm'){await api('/api/clinical-records',{method:'POST',body:JSON.stringify(Object.fromEntries(f.entries()))});toast('تم حفظ السجل الطبي');await navigate('medical')}else if(e.target.id==='videoForm'){const d=await api('/api/video-sessions',{method:'POST',body:JSON.stringify(Object.fromEntries(f.entries()))});state.lastMeetingUrl=d.meetingUrl;toast('تم إنشاء رابط الجلسة التجريبي');await navigate('video')}}catch(err){toast(err.message,true)}});
